// and not wasting food, money or time. Each lesson says what to do, what not to
// do, and why. From the Quran and ṣaḥīḥ/ḥasan ḥadīth; accounts from later books
// are labelled "reported". A scholar should review before release.

const P = (text: string): Block => ({ type: "p", text });
const L = (title: string, items: string[]): Block => ({ type: "points", title, items });

